import {
  evaluateDemolition,
  evaluateFarmPlacement,
  evaluateGranaryPlacement,
  evaluateHempFarmPlacement,
  evaluateInfantryFortPlacement,
  evaluateTaxOfficePlacement,
  evaluateTradingPostPlacement,
  evaluateHousePlacement,
