  evaluateWeaponsmithPlacement,
  emptyFoodStocks,
  foodQualityForStocks,
  calculateLaborReport,
  DEFAULT_LABOR_POLICY,
  desirabilityAtSite,
  deployedSoldiers,
  elementAtTile,
  eraStateAtTick,
  fengShuiAtSite,
  nextCitySentiment,
  migrationAttractiveness,
} from "@empire/simulation";

import { SimulationWorkerClient } from "./worker-bridge";
import {
  CROP_LABELS,
  CROP_OPTIONS,
  FOOD_QUALITY_LABELS,
  calendarLabel,
} from "./crop-catalog";
