}

.game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  outline: none;
  touch-action: none;
}

.top-bar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 88px;
  pointer-events: none;
  padding: 16px 24px;
  border-bottom: 1px solid rgb(184 154 85 / 24%);
