}

export function evaluateWeaverPlacement(
  snapshot: WorldSnapshot,
  x: number,
  y: number,
): PlacementStatus {
  return evaluateBuildingPlacement(snapshot, "weaver", x, y);
}

export function evaluateWeaponsmithPlacement(
  snapshot: WorldSnapshot,
  x: number,
  y: number,
