  width: 100%;
  height: 100%;
  isolation: isolate;
  background:
    radial-gradient(circle at 50% 30%, rgb(102 127 88 / 20%), transparent 48%),
    var(--ink);
}

.game-shell::after {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  content: "";
  background: linear-gradient(
    180deg,
    rgb(4 8 10 / 58%),
    transparent 18%,
    transparent 76%,
    rgb(4 8 10 / 70%)
  );
}

.game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  outline: none;
  touch-action: none;
}

.top-bar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 88px;
  pointer-events: none;
  padding: 16px 24px;
  border-bottom: 1px solid rgb(184 154 85 / 24%);
  background: linear-gradient(180deg, rgb(7 18 20 / 96%), rgb(13 30 31 / 76%));
  backdrop-filter: blur(12px);
  gap: 16px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--bronze);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  color: var(--paper);
  font-family: "Songti SC", STSong, serif;
  font-size: 30px;
  font-weight: 600;
  letter-spacing: 0.14em;
}

.hud {
  display: flex;
  gap: 8px;
  margin: 0;
}

.hud div {
  min-width: 84px;
  padding: 8px 12px;
  border: 1px solid rgb(184 154 85 / 20%);
  border-radius: 0;
  background: rgb(22 48 50 / 62%);
  clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 6px, 100% 100%, 0 100%);
}

.hud dt {
  margin-bottom: 3px;
  color: var(--mist);
  font-size: 10px;
  letter-spacing: 0.12em;
}

.hud dd {
  margin: 0;
  color: var(--paper);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 13px;
}

.build-dock {
  position: absolute;
  left: 24px;
  bottom: 52px;
  z-index: 5;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  width: 270px;
  padding: 8px;
  border: 1px solid rgb(184 154 85 / 35%);
  border-radius: 0;
  background: rgb(8 23 24 / 93%);
  box-shadow: 0 18px 40px rgb(0 0 0 / 32%);
  gap: 6px;
  clip-path: polygon(
    0 0,
    calc(100% - 8px) 0,
    100% 8px,
    100% 100%,
    8px 100%,
    0 calc(100% - 8px)
  );
}

.dock-label {
  display: block;
  grid-column: 1 / -1;
  margin: 0 0 0 2px;
  color: var(--bronze);
  font-size: 11px;
  letter-spacing: 0.16em;
}

.build-dock button {
  display: grid;
  width: 100%;
  padding: 5px;
  color: #827d70;
  border: 1px solid rgb(184 170 132 / 15%);
  border-radius: 3px;
  background: #111d1e;
  cursor: not-allowed;
  gap: 3px;
  place-items: center;
}

.build-dock button:not(:disabled) {
  color: #d8d0b8;
  border-color: rgb(204 181 116 / 38%);
  cursor: pointer;
}

.build-dock button:not(:disabled):hover,
.build-dock button.active {
  color: var(--paper);
  border-color: var(--bronze);
  background: #274539;
  box-shadow: inset 0 0 0 1px rgb(255 231 167 / 8%);
}

.build-dock button.well-tool .building-glyph {
  color: #71aebc;
}

.build-dock button.well-tool:not(:disabled):hover,
.build-dock button.well-tool.active {
  color: #e2f3ee;
  border-color: #71aebc;
  background: #173c43;
}

.build-dock button.farm-tool .building-glyph {
  color: #c7ad50;
}

.build-dock button.farm-tool:not(:disabled):hover,
.build-dock button.farm-tool.active {
  color: #f1e7b5;
  border-color: #a9a84e;
  background: #34452a;
}

.build-dock button.granary-tool .building-glyph {
  color: #bd7549;
}

.build-dock button.granary-tool:not(:disabled):hover,
.build-dock button.granary-tool.active {
  color: #f0d7bc;
  border-color: #bd7549;
  background: #452d20;
}

.build-dock button.market-tool .building-glyph {
  color: #d06a4b;
}

.build-dock button.market-tool:not(:disabled):hover,
.build-dock button.market-tool.active {
  color: #f3d7c7;
  border-color: var(--market-red);
  background: #4a2822;
}

.build-dock button.hemp-tool .building-glyph {
  color: #8eb260;
}

.build-dock button.hemp-tool:not(:disabled):hover,
.build-dock button.hemp-tool.active {
  color: #e0edbd;
  border-color: #8eb260;
  background: #29452a;
}

.build-dock button.weaver-tool .building-glyph {
  color: #c49a70;
}

.build-dock button.weaver-tool:not(:disabled):hover,
.build-dock button.weaver-tool.active {
  color: #f0ddca;
  border-color: #c49a70;
  background: #453528;
}

.build-dock button.weaponsmith-tool .building-glyph {
  color: #d48755;
}

.build-dock button.weaponsmith-tool:not(:disabled):hover,
.build-dock button.weaponsmith-tool.active {
  color: #f2d1b6;
  border-color: #d48755;
  background: #4a2d22;
}

.build-dock button.fort-tool .building-glyph {
  color: #c86852;
}

.build-dock button.fort-tool:not(:disabled):hover,
.build-dock button.fort-tool.active {
  color: #f1cdc4;
  border-color: #c86852;
  background: #472722;
}

.build-dock button.tax-tool .building-glyph {
  color: #c3a75f;
}

.build-dock button.tax-tool:not(:disabled):hover,
.build-dock button.tax-tool.active {
  color: #f0dfaa;
  border-color: #9d8549;
  background: #40361f;
}

.build-dock button.music-tool .building-glyph {
  color: #bc7990;
}

.build-dock button.music-tool:not(:disabled):hover,
.build-dock button.music-tool.active {
  color: #f0c6d2;
  border-color: #9b6074;
  background: #3d2730;
}

.build-dock button.trade-tool .building-glyph {
  color: #77a48f;
}

.build-dock button.trade-tool:not(:disabled):hover,
.build-dock button.trade-tool.active {
  color: #cce4d8;
  border-color: #608c79;
  background: #263d34;
}

.build-dock button.demolish-tool {
  grid-column: 1 / -1;
  grid-template-columns: auto auto;
  justify-content: center;
  min-height: 42px;
}

.build-dock button.demolish-tool .building-glyph {
  width: 28px;
  height: 28px;
  font-size: 17px;
}

.building-glyph {
  display: grid;
  width: 34px;
  height: 34px;
  color: #9d947e;
  border: 1px solid currentColor;
  place-items: center;
  font-family: "Songti SC", STSong, serif;
  font-size: 20px;
}

.crop-picker {
  position: absolute;
  left: 302px;
  bottom: 104px;
  z-index: 5;
  display: flex;
  align-items: stretch;
  padding: 7px;
  border: 1px solid rgb(184 154 85 / 35%);
  background: rgb(8 23 24 / 94%);
  box-shadow: 0 16px 34px rgb(0 0 0 / 30%);
  gap: 5px;
}

.crop-picker-title {
  display: grid;
  padding: 0 8px;
  color: var(--bronze);
  font-family: "Songti SC", STSong, serif;
  font-size: 12px;
  letter-spacing: 0.1em;
  place-items: center;
}

.crop-picker button {
  display: grid;
  min-width: 66px;
