}

.speed-panel {
  position: absolute;
  left: 302px;
  bottom: 62px;
  z-index: 5;
  display: flex;
  padding: 5px;
  border: 1px solid rgb(184 154 85 / 30%);
  background: rgb(8 23 24 / 94%);
  gap: 4px;
}

.speed-panel button {
  min-width: 42px;
  padding: 5px 8px;
  color: #aaa691;
  border: 1px solid rgb(184 170 132 / 22%);
  background: #142322;
  cursor: pointer;
}

.speed-panel button:hover,
.speed-panel button.active {
  color: #f1e7b5;
  border-color: #a9a84e;
  background: #34452a;
}

.labor-panel {
  position: absolute;
  right: 24px;
  bottom: 62px;
  z-index: 5;
  display: flex;
  align-items: center;
  padding: 6px;
  color: var(--bronze);
  border: 1px solid rgb(184 154 85 / 30%);
  background: rgb(8 23 24 / 94%);
  font-size: 11px;
  gap: 4px;
}

.labor-panel > span {
  padding: 0 5px;
