}

.labor-panel button {
  min-width: 42px;
  padding: 5px 7px;
  color: #c9c4af;
  border: 1px solid rgb(184 170 132 / 22%);
  background: #142322;
  cursor: pointer;
}

.labor-panel button:hover,
.labor-panel button.active {
  color: var(--paper);
  border-color: var(--bronze);
  background: #34452a;
}

.storage-panel {
  position: absolute;
  right: 24px;
  bottom: 106px;
  z-index: 5;
  display: flex;
  align-items: center;
  padding: 6px;
  color: var(--bronze);
  border: 1px solid rgb(184 154 85 / 30%);
  background: rgb(8 23 24 / 94%);
  font-size: 11px;
  gap: 4px;
}

.storage-panel > span {
  padding: 0 6px;
}

.storage-panel button {
  padding: 5px 8px;
  color: #8c887b;
  border: 1px solid rgb(184 170 132 / 18%);
  background: #142322;
  cursor: pointer;
}

.storage-panel button.active {
  color: #e7ddb9;
  border-color: #a9a84e;
  background: #34452a;
}

.religion-panel {
  position: absolute;
  right: 24px;
  bottom: 150px;
  z-index: 5;
  display: flex;
  align-items: center;
  padding: 6px;
  color: #d7c58d;
  border: 1px solid rgb(184 154 85 / 30%);
  background: rgb(8 23 24 / 94%);
  font-size: 11px;
  gap: 6px;
}

.religion-panel button {
  padding: 5px 9px;
  color: #e5d7ac;
  border: 1px solid #867440;
  background: #3d3520;
  cursor: pointer;
}

.religion-panel button:disabled {
  color: #777266;
  border-color: #4a463c;
  background: #1b2322;
  cursor: not-allowed;
}

.diplomacy-panel {
  position: absolute;
  right: 24px;
  bottom: 194px;
  z-index: 5;
  display: flex;
  align-items: center;
  padding: 6px;
  color: #b8cdb8;
  border: 1px solid rgb(105 146 126 / 42%);
  background: rgb(8 23 24 / 94%);
  font-size: 11px;
  gap: 8px;
}

.diplomacy-panel button {
  padding: 5px 9px;
  color: #d4e4d3;
  border: 1px solid #557d65;
  background: #263d31;
  cursor: pointer;
}

.diplomacy-panel button:disabled {
  color: #777;
  border-color: #464c47;
  background: #1b2322;
  cursor: not-allowed;
}

.tax-panel {
  position: absolute;
  right: 24px;
  bottom: 238px;
  z-index: 5;
  display: flex;
  align-items: center;
  padding: 6px;
  color: #d8c58a;
  border: 1px solid rgb(184 154 85 / 38%);
  background: rgb(8 23 24 / 94%);
  font-size: 11px;
  gap: 5px;
}

.tax-panel > span {
  padding: 0 5px;
}

.tax-panel button {
  padding: 5px 8px;
  color: #c9c4af;
  border: 1px solid rgb(184 170 132 / 22%);
  background: #142322;
  cursor: pointer;
}

.tax-panel button:hover,
.tax-panel button.active {
  color: #f1e7b5;
  border-color: #a9a84e;
  background: #40361f;
}

.status-ribbon {
  position: absolute;
  right: 24px;
  bottom: 18px;
  z-index: 5;
  display: flex;
  align-items: center;
  min-height: 34px;
  color: #d8d4c7;
  border: 1px solid rgb(184 154 85 / 28%);
  border-radius: 0;
  background:
    repeating-linear-gradient(
      90deg,
      transparent 0 15px,
      rgb(184 154 85 / 8%) 15px 16px
    ),
    rgb(8 23 24 / 94%);
  font-size: 12px;
  gap: 0;
}

.status-ribbon span {
  padding: 7px 12px;
}

.status-ribbon span + span {
  border-left: 1px solid rgb(184 154 85 / 22%);
}

.status-ribbon .food-supply {
  color: #bfd3a3;
}

.status-ribbon .food-shortage {
  color: #f0a184;
}

button:focus-visible,
.game-canvas:focus-visible {
  outline: 2px solid var(--paper);
  outline-offset: 3px;
}

@media (max-width: 1500px) {
  .top-bar {
    align-items: center;
    padding: 10px 24px;
  }

  .hud {
    display: grid;
    grid-template-columns: repeat(15, minmax(44px, 68px));
    gap: 3px;
  }

  .hud div {
    min-width: 0;
    padding: 3px 5px;
  }

  .hud dt {
    margin-bottom: 1px;
    font-size: 8px;
  }

  .hud dd {
    font-size: 10px;
  }
}

@media (max-width: 640px) {
  .top-bar {
    min-height: 72px;
    padding: 12px;
  }

  h1 {
    font-size: 22px;
  }

  .hud {
    grid-template-columns: repeat(5, minmax(44px, 58px));
  }

  .hud dt {
    margin-bottom: 1px;
    font-size: 8px;
  }

  .hud dd {
    font-size: 10px;
  }

  .build-dock {
    left: 12px;
    bottom: 58px;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    width: 176px;
  }

  .crop-picker {
    left: 12px;
    bottom: 330px;
    max-width: calc(100vw - 24px);
    overflow-x: auto;
  }

  .speed-panel {
    left: 196px;
    bottom: 58px;
  }

  .labor-panel {
    right: 12px;
    bottom: 58px;
    max-width: calc(100vw - 212px);
    overflow-x: auto;
  }

  .storage-panel {
    right: 12px;
    bottom: 98px;
    max-width: calc(100vw - 212px);
    overflow-x: auto;
  }

  .religion-panel {
    right: 12px;
    bottom: 138px;
  }

  .diplomacy-panel {
    right: 12px;
    bottom: 178px;
    max-width: calc(100vw - 212px);
    overflow-x: auto;
  }

  .status-ribbon {
    right: 12px;
    bottom: 10px;
    left: 12px;
    overflow-x: auto;
  }

  .status-ribbon span {
    flex: 0 0 auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

/* ---- Population Detail Panel ---- */

.stat-clickable {
  cursor: pointer;
  transition: border-color 0.15s;
  pointer-events: auto;
}

.stat-clickable:hover,
.stat-clickable.active {
  border-color: rgb(204 181 116 / 64%);
  background: rgb(34 72 76 / 72%);
}

.population-panel {
  position: absolute;
  top: 104px;
  right: 24px;
  bottom: 52px;
  z-index: 6;
  width: 340px;
  overflow: hidden;
  pointer-events: auto;
  border: 1px solid rgb(184 154 85 / 35%);
  background: rgb(8 23 24 / 95%);
  box-shadow: 0 18px 40px rgb(0 0 0 / 48%);
  clip-path: polygon(
    0 0,
    calc(100% - 8px) 0,
    100% 8px,
    100% 100%,
    8px 100%,
    0 calc(100% - 8px)
  );
}

.population-panel-close {
  position: absolute;
  top: 8px;
  right: 10px;
  z-index: 1;
  display: grid;
  width: 26px;
  height: 26px;
  padding: 0;
  color: var(--bronze);
  border: 1px solid rgb(184 154 85 / 25%);
  border-radius: 2px;
  background: rgb(17 29 30 / 90%);
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  place-items: center;
  transition: color 0.15s, border-color 0.15s;
}

.population-panel-close:hover {
  color: var(--paper);
  border-color: var(--bronze);
}

.population-panel-inner {
  height: 100%;
  overflow-y: auto;
  padding: 16px 20px;
  scrollbar-width: thin;
  scrollbar-color: rgb(184 154 85 / 30%) transparent;
}

.population-section {
  margin-bottom: 20px;
}

.population-section-title {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 10px;
  color: var(--paper);
  font-family: "Songti SC", STSong, serif;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.08em;
}

.population-section-count {
  color: var(--bronze);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  font-weight: 400;
}

.population-empty {
  margin: 0;
  padding: 16px 0;
  color: var(--mist);
  font-size: 12px;
  font-style: italic;
}

.population-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 8px;
}

.population-card {
  padding: 10px 12px;
  border: 1px solid rgb(184 170 132 / 15%);
  background: rgb(17 29 30 / 80%);
}

.population-card-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgb(184 154 85 / 12%);
}

.population-card-icon {
  font-size: 14px;
  line-height: 1;
}

.population-card-label {
  color: var(--paper);
  font-size: 12px;
  font-weight: 600;
}

.population-card-state {
  margin-left: auto;
  padding: 2px 6px;
  border-radius: 2px;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.population-card-state.walking,
.population-card-state.commuting {
  color: #8abbc6;
  border: 1px solid rgb(138 187 198 / 30%);
  background: rgb(138 187 198 / 10%);
}

.population-card-state.building {
  color: #d4b47a;
  border: 1px solid rgb(212 180 122 / 30%);
  background: rgb(212 180 122 / 10%);
}

.population-card-state.working {
  color: #8cc76f;
  border: 1px solid rgb(140 199 111 / 30%);
  background: rgb(140 199 111 / 10%);
}

.population-card-state.returning {
  color: #c7a06f;
  border: 1px solid rgb(199 160 111 / 30%);
  background: rgb(199 160 111 / 10%);
}

.population-card-state.resting {
  color: #a9b5a4;
  border: 1px solid rgb(169 181 164 / 30%);
  background: rgb(169 181 164 / 10%);
}

.population-card-state.strolling {
  color: #b5b0a4;
  border: 1px solid rgb(181 176 164 / 30%);
  background: rgb(181 176 164 / 10%);
}

.population-card-state.waiting {
  color: #c67a7a;
  border: 1px solid rgb(198 122 122 / 30%);
  background: rgb(198 122 122 / 10%);
}

.population-card-body {
  display: grid;
  gap: 4px;
}

.population-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 11px;
}

.population-row-label {
  color: var(--mist);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.population-row-value {
  color: var(--paper);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
}

/* ---- Clickable Cards ---- */

.clickable-card {
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}

.clickable-card:hover,
.clickable-card:focus-visible {
  border-color: rgb(204 181 116 / 48%);
  background: rgb(34 72 76 / 36%);
  outline: none;
}

/* ---- Entity Detail ---- */

.population-back-btn {
  display: inline-block;
  margin-bottom: 12px;
  padding: 4px 10px;
  color: var(--bronze);
  border: 1px solid rgb(184 154 85 / 25%);
  border-radius: 2px;
  background: transparent;
  cursor: pointer;
  font-size: 12px;
  font-family: inherit;
  transition: color 0.15s, border-color 0.15s;
}

.population-back-btn:hover {
  color: var(--paper);
  border-color: var(--bronze);
}

.entity-detail {
  padding: 0 2px;
}

.entity-detail-title {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0 0 14px;
  color: var(--paper);
  font-family: "Songti SC", STSong, serif;
  font-size: 18px;
  font-weight: 600;
}

.entity-detail-subtitle {
  margin: 0 0 8px;
  color: var(--bronze);
  font-size: 13px;
  font-weight: 500;
}

.entity-detail-section {
  margin-top: 8px;
}

.detail-row {
  padding: 5px 0;
  border-bottom: 1px solid rgb(184 154 85 / 8%);
}

.detail-rule {
  margin: 14px 0;
