  padding: 2px 6px;
  border-radius: 2px;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.population-card-state.walking,
.population-card-state.commuting {
  color: #8abbc6;
  border: 1px solid rgb(138 187 198 / 30%);
  background: rgb(138 187 198 / 10%);
}

.population-card-state.building {
  color: #d4b47a;
  border: 1px solid rgb(212 180 122 / 30%);
  background: rgb(212 180 122 / 10%);
}

.population-card-state.working {
  color: #8cc76f;
  border: 1px solid rgb(140 199 111 / 30%);
  background: rgb(140 199 111 / 10%);
}

.population-card-state.returning {
  color: #c7a06f;
  border: 1px solid rgb(199 160 111 / 30%);
  background: rgb(199 160 111 / 10%);
}

.population-card-state.resting {
  color: #a9b5a4;
  border: 1px solid rgb(169 181 164 / 30%);
  background: rgb(169 181 164 / 10%);
}

.population-card-state.strolling {
  color: #b5b0a4;
  border: 1px solid rgb(181 176 164 / 30%);
  background: rgb(181 176 164 / 10%);
}

.population-card-state.waiting {
  color: #c67a7a;
  border: 1px solid rgb(198 122 122 / 30%);
  background: rgb(198 122 122 / 10%);
}

.population-card-body {
  display: grid;
  gap: 4px;
}

.population-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 11px;
}

.population-row-label {
  color: var(--mist);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.population-row-value {
  color: var(--paper);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
}

/* ---- Clickable Cards ---- */

.clickable-card {
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}

.clickable-card:hover,
.clickable-card:focus-visible {
  border-color: rgb(204 181 116 / 48%);
  background: rgb(34 72 76 / 36%);
  outline: none;
}

/* ---- Entity Detail ---- */

.population-back-btn {
  display: inline-block;
  margin-bottom: 12px;
  padding: 4px 10px;
  color: var(--bronze);
  border: 1px solid rgb(184 154 85 / 25%);
  border-radius: 2px;
  background: transparent;
  cursor: pointer;
  font-size: 12px;
  font-family: inherit;
  transition: color 0.15s, border-color 0.15s;
}

.population-back-btn:hover {
  color: var(--paper);
  border-color: var(--bronze);
}

.entity-detail {
  padding: 0 2px;
}

.entity-detail-title {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0 0 14px;
  color: var(--paper);
  font-family: "Songti SC", STSong, serif;
  font-size: 18px;
  font-weight: 600;
}

.entity-detail-subtitle {
  margin: 0 0 8px;
  color: var(--bronze);
  font-size: 13px;
  font-weight: 500;
}

.entity-detail-section {
  margin-top: 8px;
}

.detail-row {
  padding: 5px 0;
  border-bottom: 1px solid rgb(184 154 85 / 8%);
}

.detail-rule {
  margin: 14px 0;
  border: none;
  border-top: 1px solid rgb(184 154 85 / 18%);
}

/* ---- Condition Rows ---- */

.detail-condition-list {
  display: grid;
  gap: 6px;
  margin-bottom: 4px;
}

.condition-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 4px 0;
  font-size: 11px;
}

.condition-label {
  color: var(--mist);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.condition-value {
  color: var(--paper);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
}

.condition-status {
  font-size: 11px;
}

.condition-ok .condition-status {
  color: #8cc76f;
}

.condition-fail .condition-status {
  color: #c67a7a;
}

.detail-meta {
  margin-top: 10px;
  padding-top: 6px;
  border-top: 1px solid rgb(184 154 85 / 10%);
}

.detail-hint {
  margin: 10px 0 0;
  color: #c67a7a;
  font-size: 11px;
  font-style: italic;
}

@media (prefers-reduced-motion: reduce) {
  .stat-clickable {
    transition: none;
  }
}

@media (max-width: 900px) {
  .population-panel {
    right: 12px;
    width: 280px;
  }
}

