const capabilityLabels = {
  "food-variety": "五谷轮作",
  "hemp-textiles": "麻纺",
  "bronze-infantry": "青铜步兵",
  "paper-administration": "纸张政务",
  "schools-and-rites": "学校礼制",
  cavalry: "骑兵",
