          label="五行元素"
          value={elementLabels[element]}
        />
        <ConditionRow
          label="风水格局"
          value={`${fengShui.preferredElement} · ${{
            harmonious: "吉 · 相合",
            neutral: "平",
            conflicting: "凶 · 相克",
          }[fengShui.status]}`}
