}) {
  switch (entity.kind) {
    case "migrant":
      return <MigrantDetail migrant={entity.migrant} house={entity.house} />;
    case "citizen":
      return (
        <CitizenDetail
          citizen={entity.citizen}
          house={entity.house}
          workplace={entity.workplace}
        />
      );
    case "household":
      return (
        <HouseholdDetail
